const SB_URL = 'https://kekmppsuiiokdckdeolv.supabase.co';
const SB_KEY = $env.SUPABASE_SERVICE_ROLE_KEY||'';

try {
  const resp = await this.helpers.httpRequest({
    method: 'GET',
    url: SB_URL + '/rest/v1/gateway_tasks?select=task_id,input_json,status,caller_user_id&status=eq.pending&updated_at=lt.' + Math.floor(Date.now()/1000 - 10) + '&order=created_at.asc&limit=5',
    headers: { apikey: SB_KEY, Authorization: 'Bearer ' + SB_KEY },
    json: true, returnFullResponse: true, timeout: 10000
  });
  const rows = resp.body || [];
  if (!rows.length) return [{ json: { _empty: true } }];

  return rows.map(function(r) {
    // Parse input_json properly (fix the JSON bug!)
    var input = r.input_json;
    if (typeof input === 'string') { try { input = JSON.parse(input); } catch(e) {} }
    // Unwrap envelope if wrapped
    if (input && input.envelope) { input = input.envelope; }
    return {
      json: {
        task_id: r.task_id,
        envelope: input,
        caller_user_id: r.caller_user_id || '',
        _sb_key: SB_KEY,
        _sb_url: SB_URL
      }
    };
  });
} catch(e) {
  return [{ json: { _error: String(e.message || e).slice(0, 100) } }];
}

const SB_URL = 'https://kekmppsuiiokdckdeolv.supabase.co';
const SB_KEY = $env.SUPABASE_SERVICE_ROLE_KEY||'';
const item = ($input.all()[0]||{}).json;
if (!item.task_id || item._empty || item._error) return [{ json: item }];

// Claim the task
try {
  await this.helpers.httpRequest({
    method: 'PATCH',
    url: SB_URL + '/rest/v1/gateway_tasks?task_id=eq.' + item.task_id,
    headers: {
      apikey: SB_KEY,
      Authorization: 'Bearer ' + SB_KEY,
      'Content-Type': 'application/json',
      'Prefer': 'return=minimal'
    },
    body: { status: 'in_progress' },
    json: true, timeout: 5000
  });
  return [{ json: item }];
} catch(e) {
  item._claim_error = String(e.message || e).slice(0, 100);
  return [{ json: item }];
}

const item = ($input.all()[0]||{}).json;
if (!item.task_id || item._claim_error) return [{ json: item }];

// Find a valid mxou token from the envelope extensions or task
const ext = (item.envelope || {}).extensions || {};
const token = ext.mxou_token || '';

// Call the pipeline webhook to process
try {
  const resp = await this.helpers.httpRequest({
    method: 'POST',
    url: 'http://n8n:5678/webhook/pl-v3-304140',
    headers: {
      'Content-Type': 'application/json',
      'Authorization': 'Bearer ' + token
    },
    body: {
      task_id: item.task_id,
      envelope: item.envelope,
      token: token
    },
    json: true, returnFullResponse: true, timeout: 120000
  });
  item._processed = true;
  item._pipeline_response = resp.body || {};
} catch(e) {
  item._process_error = String(e.message || e).slice(0, 200);
}
return [{ json: item }];

